import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/cn";

const button = cva("ev-btn", {
  variants: {
    variant: {
      /** Primary action — ink fill (flips to paper-on-dark). */
      primary: "ev-btn--primary",
      /** Accent CTA — the single amber fill. At most one per view. */
      accent: "ev-btn--accent",
      /** Secondary — outline, no fill. */
      secondary: "ev-btn--secondary",
      /** Quiet text button. */
      ghost: "ev-btn--ghost",
    },
    size: {
      sm: "ev-btn--sm",
      md: "ev-btn--md",
      lg: "ev-btn--lg",
    },
  },
  defaultVariants: { variant: "primary", size: "md" },
});

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof button> {}

/**
 * Evidura button. One accent per view — reserve `variant="accent"` for the
 * single most important action; everything else is `primary` or `secondary`.
 */
export const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, type = "button", ...props }, ref) => (
    <button
      ref={ref}
      type={type}
      className={cn(button({ variant, size }), className)}
      {...props}
    />
  ),
);
Button.displayName = "Button";
