import * as React from "react";
import { cn } from "../../lib/cn";
import { BandBadge, bandForScore, type Band } from "../BandBadge/BandBadge";

export interface ScoreDisplayProps
  extends React.HTMLAttributes<HTMLDivElement> {
  /** Durability score. */
  score: number;
  /** Denominator shown after the score (e.g. 100 or 110). */
  outOf?: number;
  /** Force a band; otherwise derived from the score. */
  band?: Band;
  /** Show the band pill beside the number. */
  showBand?: boolean;
}

/**
 * The durability score, set in the mono face (a score is data), with its band
 * pill beside it. Never colour the number by band — the badge carries the band.
 */
export const ScoreDisplay = React.forwardRef<
  HTMLDivElement,
  ScoreDisplayProps
>(
  (
    { score, outOf, band, showBand = true, className, ...props },
    ref,
  ) => {
    const resolved = band ?? bandForScore(score);
    return (
      <div ref={ref} className={cn("ev-score", className)} {...props}>
        <span className="ev-score__value">
          {score}
          {outOf != null && <span className="ev-score__outof">/{outOf}</span>}
        </span>
        {showBand && <BandBadge band={resolved} />}
      </div>
    );
  },
);
ScoreDisplay.displayName = "ScoreDisplay";
