import * as React from "react";
import { cn } from "../../lib/cn";

export type Band =
  | "resilient"
  | "moderate"
  | "high"
  | "critical"
  | "na";

const LABELS: Record<Band, string> = {
  resilient: "Resilient",
  moderate: "Moderate",
  high: "High",
  critical: "Critical",
  na: "N/A",
};

export interface BandBadgeProps
  extends React.HTMLAttributes<HTMLSpanElement> {
  band: Band;
  /** Override the label text (defaults to the band's name). */
  label?: string;
}

/**
 * Durability-rating band pill (Resilient → Critical). Product-UI only — this
 * is the rating scale, never the brand identity. Uses the band-colour tokens,
 * not the brand amber.
 */
export const BandBadge = React.forwardRef<HTMLSpanElement, BandBadgeProps>(
  ({ band, label, className, ...props }, ref) => (
    <span
      ref={ref}
      className={cn("ev-band", `ev-band--${band}`, className)}
      {...props}
    >
      {label ?? LABELS[band]}
    </span>
  ),
);
BandBadge.displayName = "BandBadge";

/** Map a 0–100 durability score to its band. */
export function bandForScore(score: number): Band {
  if (score >= 65) return "resilient";
  if (score >= 45) return "moderate";
  if (score >= 25) return "high";
  return "critical";
}
