import * as React from "react";
import { cn } from "../../lib/cn";

export interface ValidationSignal {
  source?: string;
  excerpt?: string;
  url?: string;
  dateDiscovered?: string;
  /** 0–5 credibility rating. */
  credibilityScore?: number;
  relevantClaim?: string;
}

export interface ValidationSignalCardProps
  extends React.HTMLAttributes<HTMLDivElement> {
  signal?: ValidationSignal | null;
}

function ExternalLinkIcon() {
  return (
    <svg
      width="14"
      height="14"
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
    >
      <path d="M15 3h6v6" />
      <path d="M10 14 21 3" />
      <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" />
    </svg>
  );
}

/**
 * A single piece of market evidence backing an assessment — source, excerpt,
 * credibility (0–5), and a link out. Refactored onto Evidura tokens.
 */
export const ValidationSignalCard = React.forwardRef<
  HTMLDivElement,
  ValidationSignalCardProps
>(({ signal, className, ...props }, ref) => {
  if (!signal) return null;

  const {
    source = "Unknown source",
    excerpt = "",
    url,
    dateDiscovered,
    credibilityScore = 0,
  } = signal;

  const clamped = Math.max(0, Math.min(5, Math.round(credibilityScore)));
  const stars = "★".repeat(clamped) + "☆".repeat(5 - clamped);

  const formattedDate = dateDiscovered
    ? new Date(dateDiscovered).toLocaleDateString("en-AU", {
        year: "numeric",
        month: "short",
        day: "numeric",
      })
    : null;

  return (
    <div
      ref={ref}
      className={cn("ev-signal", className)}
      aria-label={`Validation from ${source}, credibility ${clamped} out of 5`}
      {...props}
    >
      <div className="ev-signal__head">
        <div className="ev-signal__meta">
          <p className="ev-signal__source">{source}</p>
          <div className="ev-signal__stars" aria-hidden="true">
            {stars}
          </div>
        </div>
        <div className="ev-signal__aside">
          {formattedDate && (
            <span className="ev-signal__date">{formattedDate}</span>
          )}
          {url && (
            <a
              href={url}
              target="_blank"
              rel="noreferrer"
              className="ev-signal__link"
              aria-label={`Open source: ${source}`}
            >
              <ExternalLinkIcon />
            </a>
          )}
        </div>
      </div>
      {excerpt && <p className="ev-signal__excerpt">{excerpt}</p>}
    </div>
  );
});
ValidationSignalCard.displayName = "ValidationSignalCard";
