import * as React from "react";
import { cn } from "../../lib/cn";

export interface StrataMarkProps
  extends React.SVGProps<SVGSVGElement> {
  /** Pixel size (width & height). */
  size?: number;
  /** Render all three bars in one colour (no amber signal bar). */
  mono?: boolean;
  /** Accessible title; set to "" for a decorative mark. */
  title?: string;
}

/**
 * The Evidura primary mark (Strata-E): three stacked pill bars reading as the
 * letter E, strata of evidence, and a score made visible. Ink parts use
 * `currentColor` — set `color` on an ancestor to flip light ↔ dark. The top
 * bar is the amber signal unless `mono`.
 */
export const StrataMark = React.forwardRef<SVGSVGElement, StrataMarkProps>(
  ({ size = 40, mono = false, title = "Evidura", className, ...props }, ref) => (
    <svg
      ref={ref}
      width={size}
      height={size}
      viewBox="0 0 200 200"
      xmlns="http://www.w3.org/2000/svg"
      role="img"
      aria-label={title || undefined}
      aria-hidden={title ? undefined : true}
      className={cn("ev-mark", className)}
      {...props}
    >
      {title && <title>{title}</title>}
      <rect
        x="40"
        y="58"
        width="120"
        height="18"
        rx="9"
        fill={mono ? "currentColor" : "var(--evidura-signal)"}
      />
      <rect x="40" y="91" width="84" height="18" rx="9" fill="currentColor" />
      <rect x="40" y="124" width="120" height="18" rx="9" fill="currentColor" />
    </svg>
  ),
);
StrataMark.displayName = "StrataMark";
